?><!doctype html><html lang="<?=h($lang)?>"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Мої клікухи</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="/assets/css/sema.css?v=124"></head><body class="bg-light"><?php require __DIR__.'/partials/navbar.php';?><main class="container py-4"><h1 class="h4 mb-4"><?=$formingMode?'На формуванні':'Мої клікухи'?></h1><p><a href="/forming.php">На формуванні</a> · <a href="/my_nicknames.php">Мої клікухи</a></p><?php if($flash):?><div class="alert alert-success"><?=h($flash)?></div><?php endif;?><?php if(empty($my)):?><div class="alert alert-info">У тебе наразі немає жодної публічної або кабінетної клікухи.</div><?php else:?><div class="row g-3"><?php foreach($my as $nick):$missing=get_personality_missing_elements($pdo,(int)$nick['id']);$avatarUrl=clicuha_avatar_url($nick['avatar_path']??null);$initial=mb_strtoupper(mb_substr(trim((string)$nick['title']),0,1,'UTF-8'),'UTF-8');if($initial==='')$initial='C';?><div class="col-12 col-md-6 col-lg-4"><div class="card shadow-sm h-100 clic-gallery-card"><div class="card-body d-flex flex-column"><div class="clic-gallery-head"><a class="clic-gallery-avatar" href="/view.php?id=<?=(int)$nick['id']?>"><?php if($avatarUrl):?><img src="<?=h($avatarUrl)?>" alt="<?=h($nick['title'])?>"><?php else:?><span><?=h($initial)?></span><?php endif;?></a><div class="clic-gallery-titlebox"><h5 class="card-title mb-1"><?=h($nick['title'])?></h5><?php if($nick['slug']):?><div class="text-muted small">@<?=h($nick['slug'])?></div><?php endif;?></div></div><div class="my-2"><?php if((int)$nick['is_published']===1):?><span class="badge bg-success">Публічна</span><?php else:?><span class="badge bg-secondary">У кабінеті</span><?php endif;?></div><?php if($nick['description']):?><p class="small mt-1 mb-3"><?=nl2br(h($nick['description']))?></p><?php endif;?><div class="mb-3"><?php if($missing):?>Особистість ще не описана / формується<ul><?php foreach($missing as $item):?><li><?=h($item)?></li><?php endforeach;?></ul><?php else:?>READY<?php endif;?></div><div class="mt-auto d-flex gap-2 flex-wrap"><a class="btn btn-sm btn-outline-primary" href="/personality.php?id=<?=(int)$nick['id']?>">Особистість</a><a href="/edit_nickname.php?id=<?=(int)$nick['id']?>" class="btn btn-sm btn-primary">Редагувати</a><form method="post" class="d-inline" onsubmit="return confirm('<?=((int)$nick['is_published']===1)?'Приховати цю клікуху з Галереї та повернути в кабінет?':'Опублікувати цю клікуху в Галереї?'?>');"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=(int)$nick['id']?>"><input type="hidden" name="action" value="<?=((int)$nick['is_published']===1)?'cabinet':'publish'?>"><?php if((int)$nick['is_published']===1):?><button type="submit" class="btn btn-sm btn-outline-secondary">Приховати в кабінет</button><?php else:?><button type="submit" class="btn btn-sm btn-success" <?=$missing?'disabled':''?>>Опублікувати</button><?php endif;?></form></div></div></div></div><?php endforeach;?></div><?php endif;?></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>